insert into public.skins (item_id, target, theme) values ('pet_drone', 'character', null) on conflict (item_id) do update set target = excluded.target, theme = excluded.theme;
insert into public.items (id, category_id, slot, value, name, description, rarity_id, currency_id, price, stackable, max_quantity, sellable, purchasable, gift, grant_type, event_id, color) values ('pet_catbot', 'char', 'pet', '"catbot"'::jsonb, 'Gato Robô', 'Gato de metal azulado com olhos de LED e uma antena no lugar do rabo.', 'epic', 'gold', 140, false, null, true, true, false, 'shop', null, null) on conflict (id) do update set category_id = excluded.category_id, slot = excluded.slot, value = excluded.value, name = excluded.name, description = excluded.description, rarity_id = excluded.rarity_id, price = excluded.price, stackable = excluded.stackable, max_quantity = excluded.max_quantity, sellable = excluded.sellable, purchasable = excluded.purchasable, gift = excluded.gift, grant_type = excluded.grant_type, event_id = excluded.event_id, color = excluded.color, active = true;
insert into public.skins (item_id, target, theme) values ('pet_catbot', 'character', null) on conflict (item_id) do update set target = excluded.target, theme = excluded.theme;
insert into public.items (id, category_id, slot, value, name, description, rarity_id, currency_id, price, stackable, max_quantity, sellable, purchasable, gift, grant_type, event_id, color) values ('pet_server', 'char', 'pet', '"server"'::jsonb, 'Mini Servidor', 'Um servidorzinho com perninhas e LEDs piscando. Corre atrás de você fazendo uptime.', 'epic', 'gold', 160, false, null, true, true, false, 'shop', null, null) on conflict (id) do update set category_id = excluded.category_id, slot = excluded.slot, value = excluded.value, name = excluded.name, description = excluded.description, rarity_id = excluded.rarity_id, price = excluded.price, stackable = excluded.stackable, max_quantity = excluded.max_quantity, sellable = excluded.sellable, purchasable = excluded.purchasable, gift = excluded.gift, grant_type = excluded.grant_type, event_id = excluded.event_id, color = excluded.color, active = true;
insert into public.skins (item_id, target, theme) values ('pet_server', 'character', null) on conflict (item_id) do update set target = excluded.target, theme = excluded.theme;
