insert into public.command_help (key, cmd, example, what, when_to_use, os, sort) values ('sw-mode', 'switchport mode access|trunk', 'switchport mode access', 'access: a porta leva uma VLAN só (servidores, PCs, câmeras). trunk: leva várias VLANs marcadas (ligação entre switches).', 'Servidor ligado em porta trunk perde a rede: porta de servidor é access.', null, 41) on conflict (key) do update set cmd = excluded.cmd, example = excluded.example, what = excluded.what, when_to_use = excluded.when_to_use, os = excluded.os, sort = excluded.sort;
