insert into public.command_help (key, cmd, example, what, when_to_use, os, sort) values ('win-inherit', 'icacls <pasta> /inheritance:r', 'icacls C:\Dados\Financeiro /inheritance:r', 'Remove as permissões herdadas da pasta de cima (como BUILTIN\Users). /inheritance:d copia antes de cortar.', 'Quando uma pasta precisa ser fechada só para um grupo.', 'win', 119) on conflict (key) do update set cmd = excluded.cmd, example = excluded.example, what = excluded.what, when_to_use = excluded.when_to_use, os = excluded.os, sort = excluded.sort;
insert into public.command_help (key, cmd, example, what, when_to_use, os, sort) values ('win-share', 'New-SmbShare -Name <nome> -Path <pasta> -ChangeAccess <grupo>', 'New-SmbShare -Name Financeiro -Path C:\Dados\Financeiro -ChangeAccess "CORP\Financeiro"', 'Compartilha a pasta na rede (\\servidor\nome) com permissões de compartilhamento.', 'Para os PCs acessarem a pasta pela rede.', 'win', 120) on conflict (key) do update set cmd = excluded.cmd, example = excluded.example, what = excluded.what, when_to_use = excluded.when_to_use, os = excluded.os, sort = excluded.sort;
insert into public.command_help (key, cmd, example, what, when_to_use, os, sort) values ('win-dnszones', 'Get-DnsServerZone', 'Get-DnsServerZone', 'Lista as zonas DNS que este servidor responde.', 'Para saber em qual zona criar registros.', 'win', 121) on conflict (key) do update set cmd = excluded.cmd, example = excluded.example, what = excluded.what, when_to_use = excluded.when_to_use, os = excluded.os, sort = excluded.sort;
insert into public.command_help (key, cmd, example, what, when_to_use, os, sort) values ('win-dnsa', 'Add-DnsServerResourceRecordA -ZoneName <zona> -Name <nome> -IPv4Address <ip>', 'Add-DnsServerResourceRecordA -ZoneName corp.datalab.local -Name web -IPv4Address 10.0.1.12', 'Cria um registro A: o nome (web.corp.datalab.local) aponta para o IP.', 'Para os usuários acessarem um servidor pelo nome.', 'win', 122) on conflict (key) do update set cmd = excluded.cmd, example = excluded.example, what = excluded.what, when_to_use = excluded.when_to_use, os = excluded.os, sort = excluded.sort;
insert into public.command_help (key, cmd, example, what, when_to_use, os, sort) values ('win-dnscname', 'Add-DnsServerResourceRecordCName -ZoneName <zona> -Name <apelido> -HostNameAlias <nome completo>', 'Add-DnsServerResourceRecordCName -ZoneName corp.datalab.local -Name www -HostNameAlias web.corp.datalab.local', 'Cria um apelido (CNAME) que aponta para outro nome.', 'Para ter um nome amigável (www) sem repetir o IP.', 'win', 123) on conflict (key) do update set cmd = excluded.cmd, example = excluded.example, what = excluded.what, when_to_use = excluded.when_to_use, os = excluded.os, sort = excluded.sort;
insert into public.command_help (key, cmd, example, what, when_to_use, os, sort) values ('win-resolve', 'Resolve-DnsName <nome>  /  nslookup <nome>', 'Resolve-DnsName www.corp.datalab.local', 'Pergunta ao DNS qual o IP de um nome e mostra o caminho (CNAME → A).', 'Para testar registros DNS.', 'win', 124) on conflict (key) do update set cmd = excluded.cmd, example = excluded.example, what = excluded.what, when_to_use = excluded.when_to_use, os = excluded.os, sort = excluded.sort;
