insert into public.command_help (key, cmd, example, what, when_to_use, os, sort) values ('win-scope', 'Add-DhcpServerv4Scope -Name <nome> -StartRange <ip> -EndRange <ip> -SubnetMask 255.255.255.0', 'Add-DhcpServerv4Scope -Name LAN -StartRange 10.0.1.100 -EndRange 10.0.1.199 -SubnetMask 255.255.255.0', 'Cria a faixa de IPs que o DHCP empresta. Deixe os IPs fixos de fora.', 'Depois de instalar o DHCP.', 'win', 126) on conflict (key) do update set cmd = excluded.cmd, example = excluded.example, what = excluded.what, when_to_use = excluded.when_to_use, os = excluded.os, sort = excluded.sort;
