insert into public.problems (id, n, rank_id, title, summary, handoff, difficulty, xp, credits, skill, roles, bot_minutes, weight, trigger_kind, complete, lesson_id, when_rule, target, setup, vars, devices, bot_action, active, updated_at) values ('lead_321', 18, 'lead', 'Backup 3-2-1 do {{dev.name}}', 'A regra 3-2-1: três cópias, em dois meios diferentes, uma fora do prédio. Monte isso para o /etc e o site do {{dev.name}}.', null, 5, 240, 36, 'servidores', array[]::text[], 25, 1, 'random', 'lesson', null, null, '{"kind":"server","state":"online","os":"linux","healthy":true,"web":true}'::jsonb, '{"linux":"nobackup"}'::jsonb, '{}'::jsonb, '{"peer":"server.peer"}'::jsonb, null, true, now()) on conflict (id) do update set n = excluded.n, rank_id = excluded.rank_id, title = excluded.title, summary = excluded.summary, handoff = excluded.handoff, difficulty = excluded.difficulty, xp = excluded.xp, credits = excluded.credits, skill = excluded.skill, roles = excluded.roles, bot_minutes = excluded.bot_minutes, weight = excluded.weight, trigger_kind = excluded.trigger_kind, complete = excluded.complete, lesson_id = excluded.lesson_id, when_rule = excluded.when_rule, target = excluded.target, setup = excluded.setup, vars = excluded.vars, devices = excluded.devices, bot_action = excluded.bot_action, active = true, updated_at = now();
insert into public.problems (id, n, rank_id, title, summary, handoff, difficulty, xp, credits, skill, roles, bot_minutes, weight, trigger_kind, complete, lesson_id, when_rule, target, setup, vars, devices, bot_action, active, updated_at) values ('lead_ssh', 19, 'lead', 'Endurecer o SSH do {{dev.name}}', 'Uma auditoria achou o {{dev.name}} aceitando login de root e por senha pelo SSH. O padrão é: root nunca entra, e só com chave.', null, 5, 260, 39, 'seguranca', array[]::text[], 15, 1, 'random', 'lesson', null, null, '{"kind":"server","state":"online","os":"linux","healthy":true}'::jsonb, '{"linux":"sshroot"}'::jsonb, '{}'::jsonb, '{}'::jsonb, null, true, now()) on conflict (id) do update set n = excluded.n, rank_id = excluded.rank_id, title = excluded.title, summary = excluded.summary, handoff = excluded.handoff, difficulty = excluded.difficulty, xp = excluded.xp, credits = excluded.credits, skill = excluded.skill, roles = excluded.roles, bot_minutes = excluded.bot_minutes, weight = excluded.weight, trigger_kind = excluded.trigger_kind, complete = excluded.complete, lesson_id = excluded.lesson_id, when_rule = excluded.when_rule, target = excluded.target, setup = excluded.setup, vars = excluded.vars, devices = excluded.devices, bot_action = excluded.bot_action, active = true, updated_at = now();
insert into public.problems (id, n, rank_id, title, summary, handoff, difficulty, xp, credits, skill, roles, bot_minutes, weight, trigger_kind, complete, lesson_id, when_rule, target, setup, vars, devices, bot_action, active, updated_at) values ('lead_crise', 20, 'lead', 'Crise no datacenter', 'Tudo de uma vez: o DNS do domínio ({{dc.name}}) parou, o site do {{peer.name}} caiu e o {{dev.name}} sumiu da rede. Coordene a volta, na ordem que fizer sentido.', null, 5, 320, 48, 'gestao', array[]::text[], 40, 1, 'random', 'lesson', null, null, '{"kind":"server","state":"online","os":"linux","healthy":true,"directLink":true}'::jsonb, '{"faults":[{"fault":"winsvc","on":"dc","opts":{"svc":"DNS"}},{"fault":"disksvc","on":"peer"},{"fault":"port","on":"sw"}]}'::jsonb, '{"port":"srv.port"}'::jsonb, '{"dc":"win.dc","peer":"server.peer","sw":"switch.of"}'::jsonb, 'fix', true, now()) on conflict (id) do update set n = excluded.n, rank_id = excluded.rank_id, title = excluded.title, summary = excluded.summary, handoff = excluded.handoff, difficulty = excluded.difficulty, xp = excluded.xp, credits = excluded.credits, skill = excluded.skill, roles = excluded.roles, bot_minutes = excluded.bot_minutes, weight = excluded.weight, trigger_kind = excluded.trigger_kind, complete = excluded.complete, lesson_id = excluded.lesson_id, when_rule = excluded.when_rule, target = excluded.target, setup = excluded.setup, vars = excluded.vars, devices = excluded.devices, bot_action = excluded.bot_action, active = true, updated_at = now();
